<?php
require_once "../config/koneksi.php";require_once "../config/auth.php";require_role('admin');$title="Data Kelas";
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$aksi=$_POST['aksi']??'';if($aksi==='hapus'){$pdo->prepare("DELETE FROM kelas WHERE id=?")->execute([(int)$_POST['id']]);}else{$id=(int)($_POST['id']??0);$nama=trim($_POST['nama']);if($id)$pdo->prepare("UPDATE kelas SET nama=? WHERE id=?")->execute([$nama,$id]);else$pdo->prepare("INSERT INTO kelas(nama) VALUES(?)")->execute([$nama]);}header("Location:index.php");exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM kelas WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query("SELECT * FROM kelas ORDER BY nama")->fetchAll();include "../layout/header.php";?>
<div class="d-flex justify-content-between mb-3"><h3>Data Kelas</h3><a class="btn btn-primary" href="?tambah=1">+ Tambah</a></div>
<?php if(isset($_GET['tambah'])||$edit):?><div class="card mb-3"><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="aksi" value="simpan"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="input-group"><input class="form-control" name="nama" placeholder="Nama kelas" required value="<?=e($edit['nama']??'')?>"><button class="btn btn-success">Simpan</button></div></form></div></div><?php endif;?>
<div class="card"><div class="card-body"><table class="table table-bordered"><tr><th>No</th><th>Nama Kelas</th><th>Aksi</th></tr><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['nama'])?></td><td><a class="btn btn-sm btn-warning" href="?edit=<?=$r['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Hapus?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-danger">Hapus</button></form></td></tr><?php endforeach;?></table></div></div><?php include "../layout/footer.php";?>
